import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert, Button } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE ===================== */
const themeStyle = `
.chart-scroll { overflow-x: auto; overflow-y: hidden; }
.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
  border-radius: 8px 8px 0 0 !important;
  padding: 20px !important;
}
.history-header .card-title { color: white !important; margin: 0 !important; font-weight: bold; font-size: 1.25rem; }
.form-select { border-radius: 12px !important; padding: 8px 15px !important; border: 1px solid #e9ecef !important; font-size: 14px !important; color: #525f7f !important; }
.form-label { font-weight: 700; color: #5e72e4; text-transform: uppercase; font-size: 0.75rem; margin-bottom: 8px; }
.card { border: none !important; box-shadow: 0 0 2rem 0 rgba(136, 152, 170, 0.15) !important; margin-bottom: 30px !important; border-radius: 0.75rem !important; }
.ct-bar { cursor: pointer; transition: fill 0.2s; }
.ct-bar:hover { opacity: 0.7; }
.legend-dot { width: 12px; height: 12px; border-radius: 50%; display: inline-block; margin-right: 5px; }
.no-data-card { border: 2px dashed #e9ecef !important; background-color: #f8f9fe !important; }
`;

const CAMERA_MAP = { CAM01: "วิศวะ", CAM02: "วิทยาศาสตร์", CAM03: "ศิลปศาสตร์", CAM04: "PKY" };

function History() {
  const currentYearBE = new Date().getFullYear() + 543;
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [cameraId, setCameraId] = useState("CAM01");
  
  // นำช่วงเวลากลับมา
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");

  const [rawFileData, setRawFileData] = useState({ labels: [], series: [[]] });
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [detailChart, setDetailChart] = useState(null); 
  const [selectedHour, setSelectedHour] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" }, { val: "03", name: "มีนาคม" },
    { val: "04", name: "เมษายน" }, { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" }, { val: "09", name: "กันยายน" },
    { val: "10", name: "ตุลาคม" }, { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" },
  ];

  // สร้างรายการตัวเลือกเวลา 00:00 - 23:00
  const timeOptions = Array.from({ length: 24 }, (_, i) => {
    const hour = i.toString().padStart(2, "0") + ":00";
    return <option key={hour} value={hour}>{hour}</option>;
  });

  const handleSearch = async () => {
    setIsLoaded(false);
    setDetailChart(null);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    
    try {
      // ส่งค่า startTime และ endTime ไปยัง API
      const res = await fetch(`http://localhost:3001/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);
      const result = await res.json();

      if (result && result.labels && result.labels.length > 0) {
        setRawFileData(result);
        const bucket = {};
        result.labels.forEach((label, idx) => {
          const hour = label.split(":")[0].padStart(2, '0') + ":00";
          if (!bucket[hour]) bucket[hour] = { sum: 0, count: 0 };
          bucket[hour].sum += result.series[0][idx];
          bucket[hour].count += 1;
        });

        const labels = [], series = [];
        const startH = parseInt(startTime.split(":")[0]);
        const endH = parseInt(endTime.split(":")[0]);

        // วาดกราฟตามช่วงเวลาที่ผู้ใช้เลือก
        for (let i = startH; i <= endH; i++) {
          const h = i.toString().padStart(2, '0') + ":00";
          labels.push(h);
          series.push(bucket[h] ? Math.round(bucket[h].sum / bucket[h].count) : 0);
        }
        setChartState({ labels, series: [series] });
      } else {
        setChartState({ labels: [], series: [[]] });
        setRawFileData({ labels: [], series: [[]] });
      }
    } catch (err) { 
        console.error("Fetch error:", err);
        setChartState({ labels: [], series: [[]] });
    } finally {
        setIsLoaded(true);
    }
  };

  useEffect(() => { handleSearch(); }, [selectedDay, selectedMonth, selectedYearBE, cameraId, startTime, endTime]);

  const getDensityColor = (val) => {
    if (val >= 41) return "#f5365c"; 
    if (val >= 31) return "#fb6340"; 
    if (val >= 21) return "#ffd600"; 
    return "#2dce89"; 
  };

  const chartEvents = {
    draw: (data) => {
      if (data.type === "bar") {
        data.element.attr({ style: `stroke: ${getDensityColor(data.value.y)}; stroke-width: 25px;` });
        data.group.elem("text", { 
          x: data.x2, y: data.y2 - 12, 
          style: "font-size:12px; font-weight:bold; text-anchor:middle; fill:#525f7f;" 
        }).text(data.value.y);
      }
    },
    created: (context) => {
      if (!context.svg) return;
      context.svg._node.onclick = (e) => {
        const bar = e.target.closest('.ct-bar');
        if (!bar) return;
        const seriesGroup = bar.parentNode;
        const allBars = Array.from(seriesGroup.querySelectorAll('.ct-bar'));
        const index = allBars.indexOf(bar);

        if (index !== -1 && chartState.labels[index]) {
          const hourLabel = chartState.labels[index];
          const hourPrefix = hourLabel.split(":")[0];
          const dLabels = [], dSeries = [];
          rawFileData.labels.forEach((l, i) => {
            if (l.startsWith(hourPrefix)) {
              dLabels.push(l);
              dSeries.push(rawFileData.series[0][i]);
            }
          });
          if (dLabels.length > 0) {
            setSelectedHour(hourLabel);
            setDetailChart({ labels: dLabels, series: [dSeries] });
          }
        }
      };
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>
      <Row><Col md="12">
        <Card><Card.Header className="history-header"><Card.Title as="h4">ค้นหาข้อมูลย้อนหลังตามช่วงเวลา</Card.Title></Card.Header>
          <Card.Body><Row className="align-items-end g-3">
            <Col md="3"><Form.Label className="form-label">สถานที่</Form.Label>
              <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                {Object.entries(CAMERA_MAP).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
              </Form.Select></Col>
            
            <Col md="5"><Form.Label className="form-label">เลือกวันที่</Form.Label><div className="d-flex gap-2">
              <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>{Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</Form.Select>
              <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>{monthsThai.map(m=><option key={m.val} value={m.val}>{m.name}</option>)}</Form.Select>
              <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}><option value={currentYearBE}>{currentYearBE}</option><option value={currentYearBE-1}>{currentYearBE-1}</option></Form.Select>
            </div></Col>

            {/* ส่วนเลือกช่วงเวลากลับมาแล้ว */}
            <Col md="4"><Form.Label className="form-label">ช่วงเวลา</Form.Label><div className="d-flex align-items-center gap-2">
              <Form.Select value={startTime} onChange={(e) => setStartTime(e.target.value)}>{timeOptions}</Form.Select>
              <span>ถึง</span>
              <Form.Select value={endTime} onChange={(e) => setEndTime(e.target.value)}>{timeOptions}</Form.Select>
            </div></Col>
          </Row></Card.Body></Card>
      </Col></Row>

      {isLoaded && chartState.labels.length > 0 ? (
        <>
          <Card><Card.Body>
            <div className="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-2">
              <h5 className="mb-0 text-primary font-weight-bold">สถิติความหนาแน่น: {startTime} - {endTime}</h5>
              <div className="d-flex gap-3 flex-wrap">
                <div className="small"><span className="legend-dot" style={{background:'#2dce89'}}></span> 0-20</div>
                <div className="small"><span className="legend-dot" style={{background:'#ffd600'}}></span> 21-30</div>
                <div className="small"><span className="legend-dot" style={{background:'#fb6340'}}></span> 31-40</div>
                <div className="small"><span className="legend-dot" style={{background:'#f5365c'}}></span> 41+</div>
              </div>
            </div>
            <div className="chart-scroll"><div style={{ width: "100%", minWidth: "800px", height: "400px" }}>
              <ChartistGraph data={chartState} type="Bar" options={{ low: 0, fullWidth: true, chartPadding: { top: 30, right: 20 } }} listener={chartEvents} />
            </div></div>
          </Card.Body></Card>

          {detailChart && (
            <Card className="border-primary" style={{borderWidth:'2px', borderStyle:'solid'}}>
              <Card.Header className="bg-light d-flex justify-content-between align-items-center py-3">
                <h5 className="mb-0 font-weight-bold text-primary">🔍 รายละเอียดรายนาที: {selectedHour} น.</h5>
                <Button variant="outline-danger" size="sm" onClick={() => setDetailChart(null)}>ปิด</Button>
              </Card.Header>
              <Card.Body>
                <div className="chart-scroll"><div style={{ width: "100%", minWidth: "1200px", height: "350px" }}>
                  <ChartistGraph 
                    data={detailChart} 
                    type="Line" 
                    options={{ 
                        low: 0, showArea: true, fullWidth: true,
                        axisX: { labelInterpolationFnc: (value, index) => index % 5 === 0 ? value : null, offset: 60 }
                    }} 
                  />
                </div></div>
              </Card.Body>
            </Card>
          )}
        </>
      ) : (
        isLoaded && (
          <Card className="no-data-card py-5 text-center">
            <Card.Body>
              <div className="mb-3"><span style={{ fontSize: "50px" }}>📁</span></div>
              <h3 className="text-muted font-weight-bold">ไม่พบข้อมูลสถิติ</h3>
              <p className="text-muted mb-0">ไม่พบข้อมูลในช่วงเวลา {startTime} ถึง {endTime}</p>
              <Alert variant="info" className="d-inline-block mt-3 px-4 shadow-sm">ลองปรับช่วงเวลาหรือเปลี่ยนวันที่</Alert>
            </Card.Body>
          </Card>
        )
      )}
    </Container>
  );
}

export default History;
